'use strict';
const fs=require('fs'); const path=require('path');
const root=process.env.GITHUB_WORKSPACE||process.cwd(); const qdir=path.join(root,'qualification','learning');
const evidenceDir=path.join(process.env.RUNNER_TEMP||root,process.env.EVIDENCE_DIR||'learning-dependency-adjudication-evidence'); fs.mkdirSync(evidenceDir,{recursive:true});
const load=(n)=>JSON.parse(fs.readFileSync(path.join(qdir,n),'utf8')); const base=(p)=>path.basename(p);
const fail=(code,detail='')=>{const failure=detail?`${code}:${detail}`:code;fs.writeFileSync(path.join(evidenceDir,'failure-summary.json'),JSON.stringify({subject_sha:process.env.GITHUB_SHA||'LOCAL',result_class:'FAIL',failure},null,2)+'\n');throw new Error(failure);};
const candidateName=process.env.DEPENDENCY_CANDIDATE; const expectedControl=process.env.EXPECTED_CONTROL_HEAD; const start=Number(process.env.START_INDEX); const expectedCount=Number(process.env.EXPECTED_COUNT); const cumulative=Number(process.env.CUMULATIVE_COUNT); const remaining=Number(process.env.REMAINING_COUNT);
if(!candidateName||!expectedControl||!Number.isInteger(start)||!Number.isInteger(expectedCount)) fail('ENV');
const contract=load('LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001C-DEPENDENCY-EVIDENCE-ADJUDICATION-CONTRACT-044.json'); const candidate=load(candidateName); const structural=load('LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001A-FULL-GRAPH-CLOSURE-CANDIDATE-024A.json'); const assessment=load('LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001B-ASSESSMENT-TARGET-FULL-CLOSURE-CANDIDATE-042A.json');
if(candidate.base_control_head!==expectedControl) fail('CONTROL_HEAD_DRIFT'); if(candidate.contract!=='qualification/learning/LEARNING-FULL-STANDARD-CURRICULUM-COMPILER-001C-DEPENDENCY-EVIDENCE-ADJUDICATION-CONTRACT-044.json') fail('CONTRACT');
const topologyPaths=[structural.cumulative_inputs.domain_i_base,...structural.cumulative_inputs.bounded_candidates]; const universe=[]; const byId=new Map(); const parents=new Set();
for(const p of topologyPaths){const t=load(base(p)); for(const s of t.subskills||[]) parents.add(s.parent_requirement_id); for(const u of t.unresolved_dependency_candidates||[]){if(u.admission_status!=='UNRESOLVED__NOT_CANONICAL') fail('SOURCE_STATUS',u.candidate_id); const x={...u,source_topology_artifact:p}; universe.push(x); byId.set(x.candidate_id,x);}}
if(universe.length!==46) fail('UNIVERSE',String(universe.length)); if(parents.size!==66) fail('SUBSKILLS',String(parents.size));
const allTargets=[]; for(const n of assessment.assessment_batches){const b=load(n); allTargets.push(...b.targets);} const targetParents=new Set(allTargets.map(t=>t.parent_requirement_id)); if(allTargets.length!==66||targetParents.size!==66) fail('ASSESSMENTS');
if(!Array.isArray(candidate.dispositions)||candidate.dispositions.length!==expectedCount||candidate.selected_candidate_count!==expectedCount) fail('COUNT'); const ids=candidate.dispositions.map(d=>d.candidate_id); const expected=universe.slice(start,start+expectedCount).map(u=>u.candidate_id); if(JSON.stringify(ids)!==JSON.stringify(expected)) fail('SELECTION',JSON.stringify({expected,ids}));
const allowed=new Set(contract.allowed_dispositions); const seen=new Set(); let admitted=0,rejected=0,unresolved=0,deferred=0;
for(const d of candidate.dispositions){if(seen.has(d.candidate_id)) fail('DUPLICATE',d.candidate_id); seen.add(d.candidate_id); const src=byId.get(d.candidate_id); if(!src||src.from_id!==d.from_id||src.to_id!==d.to_id||src.source_topology_artifact!==d.source_topology_artifact) fail('SOURCE_DRIFT',d.candidate_id); if(!allowed.has(d.disposition)) fail('DISPOSITION',d.candidate_id); if(!targetParents.has(d.from_id)||!targetParents.has(d.to_id)) fail('ENDPOINT_TARGET',d.candidate_id); if(!Array.isArray(d.evidence_refs)||d.evidence_refs.length<4||String(d.rationale||'').length<40) fail('EVIDENCE',d.candidate_id); if(d.disposition==='REJECT_AS_HARD_PREREQUISITE'){rejected++; if(!d.material_dependency_test||d.material_dependency_test.target_independently_performable!==true||String(d.material_dependency_test.basis||'').length<40) fail('REJECTION_TEST',d.candidate_id);} else if(d.disposition==='REMAIN_UNRESOLVED__NOT_CANONICAL') unresolved++; else if(d.disposition==='DEFER_TO_SEPARATE_HUMAN_OR_SME_EVIDENCE') deferred++; else admitted++;}
if((candidate.admitted_prerequisite_edges||[]).length!==admitted) fail('ADMITTED_EDGE_COUNT'); const bs=candidate.batch_summary; if(!bs||bs.admitted!==admitted||bs.rejected_as_hard_prerequisite!==rejected||bs.remain_unresolved_not_canonical!==unresolved||bs.deferred_to_human_or_sme!==deferred) fail('SUMMARY'); for(const [k,v] of Object.entries(contract.evidence_boundaries)) if(candidate.evidence_boundaries[k]!==v) fail('BOUNDARY',k);
const summary={subject_sha:process.env.GITHUB_SHA||'LOCAL',result_class:'PASS',batch_index:candidate.batch_index,unresolved_candidate_universe_count:46,selected_candidate_count:expectedCount,cumulative_disposition_count:cumulative,remaining_candidate_count:remaining,dispositions:{admitted,rejected_as_hard_prerequisite:rejected,remain_unresolved_not_canonical:unresolved,deferred_to_human_or_sme:deferred},frozen_requirement_count:66,frozen_subskill_count:66,frozen_assessment_target_count:66,next_objective:candidate.next_batch_on_pass,authority_boundary:'HOSTED_MACHINE_EVIDENCE_ONLY__NO_HUMAN_SME_A01_NATIVE_OR_PRODUCTION_AUTHORITY_INFERRED'}; fs.writeFileSync(path.join(evidenceDir,'qualification-summary.json'),JSON.stringify(summary,null,2)+'\n'); console.log(JSON.stringify(summary));
